style.css:
@-moz-document domain("youtube.com") {
:root {
    /* ---- EDIT THESE TO CHANGE YOUR PALETTE ---- */
    --yt-bg-main:      #1c140f;   /* main page background — dark espresso */
    --yt-bg-elevated:  #2b1f17;   /* cards, sidebar, header — coffee brown */
    --yt-bg-hover:     #3d2c20;   /* hover states — warm mocha */
    --yt-text-main:    #ede0d1;   /* primary text — cream */
    --yt-text-dim:     #b9a189;   /* secondary text — soft tan */
    --yt-accent:       #c8925a;   /* links, active icons, progress bar — antique gold */
    --yt-accent-hover: #dcae7c;   /* accent hover state — lighter gold */
    --yt-border:       #4a3728;   /* dividers, borders — dark mocha */

    /* ---- PUT YOUR IMAGE URL HERE ---- */
    --yt-bg-image: url("https://static.vecteezy.com/system/resources/thumbnails/037/918/540/small/ai-generated-trendy-leopard-fur-texture-golden-fur-and-black-spots-natural-animal-furry-background-concept-is-softness-comfort-and-luxury-can-be-used-as-backdrop-fashion-textile-interior-photo.jpeg");
    /* -------------------------------------------- */
  }

  /* Background image on the outermost page element */
  html {
    background-image: var(--yt-bg-image) !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* Page + top-level backgrounds */
  body,
  ytd-app,
  #page-manager,
  ytd-watch-flexy,
  ytd-browse {
    background-color: transparent !important;
    color: var(--yt-text-main) !important;
  }

  /* Keep the main content area readable over the image —
     give it a semi-transparent version of the main bg color.
     Edit the alpha (last value) to taste, 0 = fully see-through, 1 = solid. */
  #content,
  ytd-page-manager {
    background-color: rgba(28, 20, 15, 0.75) !important;
  }

  /* Header / masthead */
  #masthead-container,
  ytd-masthead {
    background-color: var(--yt-bg-elevated) !important;
    border-bottom: 1px solid var(--yt-border) !important;
  }

  /* Sidebar / guide */
  ytd-guide-renderer,
  tp-yt-app-drawer,
  #guide-content {
    background-color: var(--yt-bg-elevated) !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background-color: var(--yt-bg-hover) !important;
  }

  /* Video cards / thumbnails grid */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-compact-video-renderer {
    background-color: transparent !important;
  }

  /* Titles and metadata text */
  #video-title,
  .ytd-video-meta-block,
  yt-formatted-string {
    color: var(--yt-text-main) !important;
  }

  #metadata-line,
  .ytd-channel-name,
  #owner-text a {
    color: var(--yt-text-dim) !important;
  }

  /* Links + accent color elements */
  a,
  #owner-text a:hover,
  ytd-subscribe-button-renderer {
    color: var(--yt-accent) !important;
  }

  /* Buttons (subscribe, etc.) */
  ytd-subscribe-button-renderer tp-yt-paper-button {
    background-color: var(--yt-accent) !important;
    color: var(--yt-bg-main) !important;
  }

  ytd-subscribe-button-renderer tp-yt-paper-button:hover {
    background-color: var(--yt-accent-hover) !important;
  }

  /* Progress bar / scrubber */
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background-color: var(--yt-accent) !important;
  }

  /* Search bar */
  #search-input,
  ytd-searchbox {
    background-color: var(--yt-bg-elevated) !important;
    border-color: var(--yt-border) !important;
  }

  /* Comments section */
  ytd-comments,
  ytd-comment-thread-renderer,
  ytd-comment-renderer {
    background-color: var(--yt-bg-main) !important;
    color: var(--yt-text-main) !important;
  }

  /* Chips / filter bar */
  ytd-feed-filter-chip-bar-renderer,
  yt-chip-cloud-chip-renderer {
    background-color: var(--yt-bg-elevated) !important;
    color: var(--yt-text-dim) !important;
  }

  yt-chip-cloud-chip-renderer[selected] {
    background-color: var(--yt-accent) !important;
    color: var(--yt-bg-main) !important;
  }

  /* Scrollbar (Chrome/Edge) */
  ::-webkit-scrollbar {
    background-color: var(--yt-bg-main) !important;
  }
  ::-webkit-scrollbar-thumb {
    background-color: var(--yt-border) !important;
    border-radius: 8px;
  }
}
